css:
.p24-page { display: flex; flex-direction: column; gap: var(--s-2); min-height: calc(100cqh - 2 * var(--s-3)); }
.p24-top { display: grid; gap: var(--s-2); }
.p24-top:empty { display: none; }
.p24-stage { position: relative; container-type: size; container-name: p24-stage; flex: 1 1 18rem; min-height: 0; display: flex; align-items: center; justify-content: center; gap: var(--s-2); }
.p24-vp { flex: 0 1 auto; min-width: 0; max-width: calc(100cqw - 4rem); max-height: 100cqh; }
.p24-vp .scheme { width: max(34.75rem, min(calc(100cqw - 4.25rem), calc(100cqh * 1.4912 - 2 * var(--w2)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p24-stage { flex-basis: var(--stage-n, 24.5rem); } }
.p24-tb { position: relative; flex: none; align-self: flex-start; margin-top: var(--s-1); }
.p24-tb .toolbar { gap: var(--s-1); }
.p24-sep { height: var(--w1); background: var(--rule); margin: 0 var(--s-1); }
.p24-tiprow { display: flex; }
.p24-tiprow--end { justify-content: flex-end; }
.p24-tiprow--center { justify-content: center; }
.p24-tiprow .tip { max-width: 100%; }
.p24-pop { position: absolute; z-index: 6; left: calc(var(--x) * 1%); top: calc(var(--y) * 1%); width: max-content; max-width: 15rem; }
.p24-pop--tl { translate: 0 0; }
.p24-pop--c { translate: -50% -50%; }
.p24-pop--tr { translate: -100% 0; }
.p24-pop--bl { translate: 0 -100%; }
.p24-pop--br { translate: -100% -100%; }
.p24-pop--bc { translate: -50% -100%; }
.p24-pop--tc { translate: -50% 0; }
.p24-pop .tip { display: block; max-width: none; }
.p24-tip-lines { display: grid; gap: var(--s-1); }
.p24-tip-lines b { font-weight: var(--fw-bold); }
.scard.frame--full { padding: var(--s-1); }
.scard .scard__name { overflow-wrap: break-word; hyphens: manual; }
.p24-dots { position: absolute; right: 0; bottom: 0; display: none; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p24-dots { display: block; } }
.scard.p24-drag { --frame-color: var(--ink); --frame-w: var(--w2); }
.scard.p24-mini { position: relative; left: auto; top: auto; width: 3.75rem; height: 3.75rem; aspect-ratio: auto; flex: none; }
.p24-un { display: grid; gap: var(--s-2); max-height: 11.25rem; overflow: auto; }
.p24-un__row { display: flex; flex-wrap: wrap; gap: var(--s-2); }
.p24-un.is-over { border: var(--w2) dashed var(--ink); }
.p24-uphint { max-width: none; }
.p24-uptip { display: flex; justify-content: center; }
.p24-uptip .tip { max-width: none; }
.p24-btnwrap { position: relative; display: inline-flex; }
.p24-note { margin-inline-end: auto; }
.p24-err { --frame-w: var(--w2); }
.p24-btnrow { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--s-2); }
.p24-btnrow > .p24-note { flex: 1 1 100%; text-align: center; margin: 0; }
.p24-btnrow > .p24-spacer { display: none; }
.p24-btnrow > .p24-note:empty { display: none; }
.p24-btnwrap .btn[aria-disabled="true"] { cursor: not-allowed; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  .p24-btnrow > .p24-note, .p24-btnrow > .p24-spacer { display: block; flex: 1 1 0; min-width: 0; text-align: start; }
  .p24-btnrow > .p24-note:empty { display: block; }
}
.p24-load { justify-content: center; padding: var(--s-6) var(--s-3); }
.p24-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; justify-items: center; align-content: center; gap: var(--s-3); text-align: center; flex: 1; padding: var(--s-5) var(--s-3); }
.p24-center p { max-width: var(--measure); }
.p24-schint { display: flex; align-items: center; justify-content: center; gap: var(--s-1); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p24-schint { display: none; } }

.p24-cmt.frame { --cw: 12rem; position: absolute; z-index: 4; left: calc(var(--x) * 1%); top: calc(var(--y) * 1%); translate: -50% -50%; display: flex; align-items: center; gap: var(--s-1); width: var(--cw); min-height: 2.875rem; padding: 0 0 0 var(--s-3); border-radius: 50% 50% 50% var(--r); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p24-cmt.frame { --cw: 10.5rem; } }
.p24-cmt__t { flex: 1; min-width: 0; font-size: var(--fs-small); line-height: var(--lh-small); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.p24-cmt__ag { flex: none; }
.p24-cmt--open.frame { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto 1fr auto; align-items: center; gap: 0 var(--s-1); width: 17.5rem; min-height: 9.375rem; padding: var(--s-1) var(--s-3); border-radius: var(--r-soft) var(--r-soft) var(--r-soft) var(--r); translate: -50% 0; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p24-cmt--open.frame { width: 16.875rem; min-height: 8.75rem; } }
.p24-cmt--open .p24-cmt__ag { grid-column: 1; grid-row: 1; justify-self: start; }
.p24-cmt__acts { grid-column: 2; grid-row: 1; display: flex; align-items: center; }
.p24-cmt__body { grid-column: 1 / -1; grid-row: 2; align-self: start; max-height: 6.5rem; overflow: auto; font-size: var(--fs-small); line-height: var(--lh-small); overflow-wrap: anywhere; }
.p24-cmt__fold { grid-column: 1 / -1; grid-row: 3; justify-self: center; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p24-vp.is-focus { overflow: hidden; height: var(--vph, auto); }
  .p24-vp.is-focus .scheme { --sw: 34.75rem; --sh: calc(34.75rem / 1.4912); --vw: calc(100cqw - 4rem); --vh: var(--vph, min(100cqh, var(--sh)));
    translate: clamp(calc(var(--vw) - var(--sw)), calc(var(--vw) / 2 - var(--cx, 50) * var(--sw) / 100), 0px) clamp(calc(var(--vh) - var(--sh)), calc(var(--vh) / 2 - var(--cy, 50) * var(--sh) / 100), 0px); }
}

.p24-opts { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--s-2); border: 0; padding: 0; margin: 0; min-width: 0; }
.p24-opt.check { display: flex; align-items: flex-start; gap: var(--s-3); width: 100%; padding: var(--s-2) var(--s-3); min-height: 3rem; }
.p24-opt .check__box { flex: none; margin-top: var(--w1); }
.p24-opt__t { display: grid; gap: var(--s-1); min-width: 0; }
.p24-opt__n { font-weight: var(--fw-semibold); font-size: var(--fs-body); line-height: var(--lh-small); }
.p24-opt__d { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p24-opt.is-sel .p24-opt__n { color: var(--blue); font-weight: var(--fw-bold); }
.p24-ok { margin-inline-start: auto; align-self: center; color: var(--blue); flex: none; }
.p24-tipslot { display: flex; justify-content: flex-end; padding: var(--s-2) var(--s-4) 0; }
.p24-errwrap { padding: var(--s-2) var(--s-4) 0; }
.p24-err { --frame-w: var(--w2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }

.p24-un.unplaced--layers { max-height: 15rem; gap: var(--s-2); }
.p24-un.unplaced--layers .p24-un__row { gap: calc(var(--scard-off) + var(--s-2)); padding-right: var(--scard-off); }
.scard.p24-mini { overflow: visible; }
.p24-un__row { isolation: isolate; }

.scard.p24-mini .p24-dots { display: none; }
@media (max-width: 22.5rem) {
  .p24-stage { flex-direction: column; align-items: center; justify-content: flex-start; gap: var(--s-1); }
  .p24-stage { flex-basis: calc(var(--stage-n, 24.5rem) + 3.75rem); }
  .p24-tb { order: -1; align-self: center; margin-top: 0; }
  .p24-tb .toolbar { flex-direction: row; }
  .p24-sep { width: var(--w1); height: auto; align-self: stretch; margin: var(--s-1) 0; }
  .p24-vp { max-width: 100cqw; max-height: calc(100cqh - 3.75rem); }
  .p24-vp.is-focus .scheme { --vw: 100cqw; --vh: var(--vph, min(calc(100cqh - 3.75rem), var(--sh))); }
}
